import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BZRC44LV.js";const l="/dev/screenshots/table-insert.gif",d="/dev/screenshots/table-header.gif",n="/dev/screenshots/table-cells.gif",r="/dev/screenshots/table-mode.gif",i="/dev/screenshots/table-mouse.gif",c="/dev/screenshots/table-paste.gif",k=JSON.parse('{"title":"Tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tables.md","filePath":"guide/tables.md"}'),h={name:"guide/tables.md"};function p(g,e,m,b,u,w){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h1><p>Tables in Blank work like the rest of your writing: you type, press <code>Tab</code> to go to the next cell, and the table grows as you need it. The columns stay put while you type, and nothing is ever lost by a key pressed at the wrong time. Your tables are saved as plain markdown tables that GitHub, Obsidian, Typora and pandoc show as tables too.</p><img class="shot" src="'+l+'" alt="Mod T opens a grid, the arrow keys make it four columns wide, Enter inserts the table, Tab fills it cell by cell and the arrow key leads out of it"><h2 id="make" tabindex="-1">Make a table <a class="header-anchor" href="#make" aria-label="Permalink to &quot;Make a table {#make}&quot;">​</a></h2><p>There are three ways:</p><ul><li><p><strong><code>Mod</code> <code>T</code></strong> shows a small grid under the cursor. Pick the size with the arrow keys and press Enter, or point at the size and click. Want the usual? <code>Mod</code> <code>T</code> then Enter gives you three columns with a header row and two rows.</p></li><li><p><strong>Type the header.</strong> On an empty line, type the column titles between pipes and press Enter:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Name | Qty | Price |</span></span></code></pre></div><p>The line becomes a table with that header and an empty row, and the cursor waits in the first cell. Changed your mind? <code>Mod</code> <code>Z</code> gives you back the line as you typed it.</p><img class="shot" src="'+d+'" alt="Typing | Name | Role | and Enter turns the line into a table, which Tab then fills"></li><li><p><strong>Paste one</strong> from a spreadsheet, a web page or Word, see <a href="#clipboard">Copy and paste</a>.</p></li></ul><p>The first row is the header. It&#39;s bold and tinted, and screen readers announce it with every cell.</p><h2 id="move" tabindex="-1">Move around <a class="header-anchor" href="#move" aria-label="Permalink to &quot;Move around {#move}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>Next cell, with its text selected so you can type over it</td></tr><tr><td><code>Shift</code> <code>Tab</code></td><td>Previous cell</td></tr><tr><td><code>Tab</code> in the last cell</td><td>Adds a row and moves into it</td></tr><tr><td>Arrow keys</td><td>Move through the text and from cell to cell</td></tr></tbody></table><p><strong>You can&#39;t get stuck in a table.</strong> The arrow keys leave it at every edge: down from the last row, up from the first, right from the end of the last cell and left from the start of the first. Blank always keeps an empty line before a table at the start of the document, after one at the end and between two tables, so there&#39;s always a place to click and write.</p><h2 id="cells" tabindex="-1">Write in a cell <a class="header-anchor" href="#cells" aria-label="Permalink to &quot;Write in a cell {#cells}&quot;">​</a></h2><p>A cell is a small page of its own. Bold, italic, code, links and images all work in it, and so do several paragraphs, lists, quotes and code blocks. Only headings, tables and horizontal lines stay outside cells.</p><img class="shot" src="'+n+'" alt="Enter starts a second line in a cell; Shift and the left arrow select two cells, which Backspace clears"><ul><li><strong>Enter</strong> starts a new line in the cell.</li><li><strong>Enter on an empty line</strong> turns it into a new paragraph.</li><li><strong>Lists and quotes</strong>: <code>Mod</code> <code>8</code> starts a bullet list in the cell, <code>Mod</code> <code>9</code> a numbered one and <code>Mod</code> <code>G</code> a quote. Inside them, Enter continues the list as usual.</li></ul><p>Typing <code>1. </code>, <code>- </code> or <code>&gt; </code> at the start of a cell keeps the text as you typed it, since cells often hold values like <em>1. place</em> rather than lists. For the same reason, Blank doesn&#39;t capitalize the first word of a cell, so <code>kg</code>, <code>n/a</code> or <code>yes</code> stay as they are.</p><h2 id="select" tabindex="-1">Select and delete <a class="header-anchor" href="#select" aria-label="Permalink to &quot;Select and delete {#select}&quot;">​</a></h2><p><code>Shift</code> + arrow keys selects whole cells as soon as the selection crosses a cell border. The selected cells are tinted.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Backspace</code> or <code>Delete</code></td><td>Clears the selected cells, rows and columns stay</td></tr><tr><td><code>Mod</code> <code>A</code></td><td>Selects the cell, then the whole table, then everything</td></tr><tr><td><code>Backspace</code> on the whole table</td><td>Deletes the table</td></tr></tbody></table><p>To delete a table, click the bin on its toolbar, or press <code>Mod</code> <code>A</code> twice in it and then <code>Backspace</code>. Or press <code>Backspace</code> at the start of the line after the table: the first press selects the table, the second deletes it. A table you just made and haven&#39;t written in yet goes away with <code>Backspace</code> in its first cell. <code>Mod</code> <code>Z</code> brings anything back.</p><h2 id="change" tabindex="-1">Change a table <a class="header-anchor" href="#change" aria-label="Permalink to &quot;Change a table {#change}&quot;">​</a></h2><p>While the cursor is in a table, a small toolbar sits above its right end. It adds and deletes rows and columns, aligns columns, sorts, merges cells, switches the header row and a header column on and off, and sets the caption. Everything on it works on what you&#39;ve selected: with three rows selected, <em>Insert row below</em> adds three rows, and <em>Align right</em> aligns every selected column. Rest the pointer on a button to see what it does.</p><img class="shot" src="'+r+'" alt="Mod T shows a key on every button of the table toolbar; the down arrow adds a row, S sorts by the column, R aligns it right, and Esc ends table mode"><p><strong>From the keyboard:</strong> press <code>Mod</code> <code>T</code> in a table. Every button of the toolbar shows its key, and the keys work until you press <code>Esc</code> or <code>Mod</code> <code>T</code> again:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code> / <code>←</code> <code>→</code></td><td>Insert rows above or below / columns left or right</td></tr><tr><td><code>Shift</code> + <code>↑</code> <code>↓</code> / <code>←</code> <code>→</code></td><td>Move the selected rows / columns</td></tr><tr><td><code>Backspace</code> / <code>Shift</code> <code>Backspace</code></td><td>Delete the selected rows / columns</td></tr><tr><td><code>Mod</code> <code>Backspace</code></td><td>Delete the table</td></tr><tr><td><code>L</code> <code>C</code> <code>R</code></td><td>Align the selected columns left, centered or right</td></tr><tr><td><code>S</code></td><td>Sort by this column; press again to sort the other way</td></tr><tr><td><code>M</code></td><td>Merge the selected cells, or split a merged cell</td></tr><tr><td><code>H</code> / <code>Shift</code> <code>H</code></td><td>Header row / header column on or off</td></tr><tr><td><code>T</code></td><td>Write the caption, Enter keeps it</td></tr><tr><td><code>W</code></td><td>Reset the column widths you set with the mouse</td></tr></tbody></table><p>The letters stay where they are on your keyboard, whatever its layout. Any other key ends table mode without typing anything, and shortcuts like <code>Mod</code> <code>S</code> still do their job.</p><p><strong>From the menu:</strong> right-click a cell and open <em>Table</em>, which has everything, including moving rows and columns.</p><p>A few things good to know:</p><ul><li><strong>Sorting</strong> keeps the header row on top and puts empty cells last. Numbers sort by their value, also with a decimal comma like <em>1,5</em> in German, dates by their day, and text the way your language sorts it, <em>item 9</em> before <em>item 10</em>.</li><li><strong>Rows move below the header</strong> and a header column stays first. Deleting the header row makes the row below it the header.</li><li><strong>Merged cells</strong> keep everything they held. Splitting a cell leaves its content in the first cell.</li><li>The status bar at the bottom says what happened, next to the word count, like <em>2 rows added</em>, and screen readers read it out.</li></ul><h2 id="mouse" tabindex="-1">Change a table with the mouse <a class="header-anchor" href="#mouse" aria-label="Permalink to &quot;Change a table with the mouse {#mouse}&quot;">​</a></h2><p>Move the mouse over a table and it shows handles right where you need them. They step aside while you type.</p><img class="shot" src="'+i+'" alt="Dragging the handle of the Kiwis row moves it to the top; the + between two rows inserts one, which gets filled; dragging the line between two columns widens the first; dragging the bottom edge adds two rows"><ul><li><strong>Move rows and columns:</strong> grab the handle on the left edge of a row, or on the top edge of a column, and drag it where it should go. A line shows where it lands. With several rows selected, dragging one of their handles moves them all.</li><li><strong>Select them:</strong> click a handle. The row or column gets selected and the table menu opens right there, to delete it, align it, sort by it and more.</li><li><strong>Insert one:</strong> point at the line between two rows on the table&#39;s left edge, or between two columns on its top edge, and click the <strong>+</strong> that shows up.</li><li><strong>Resize columns:</strong> drag the line between two columns. The columns on both sides share their width anew, and the table keeps its width. A double click on the line gives the columns their widths by content again, as does <em>Reset column widths</em> in the table menu.</li><li><strong>Grow and shrink the table:</strong> drag its right edge, its bottom edge or its corner. A dashed outline shows the new size, like <em>4 × 6</em>. Growing adds empty rows and columns at the end; shrinking only takes away empty ones, so nothing you wrote gets lost.</li></ul><p><code>Esc</code> cancels a drag, and <code>Mod</code> <code>Z</code> undoes any change in one step.</p><h2 id="clipboard" tabindex="-1">Copy and paste <a class="header-anchor" href="#clipboard" aria-label="Permalink to &quot;Copy and paste {#clipboard}&quot;">​</a></h2><p>Tables move between Blank and your spreadsheet in both directions.</p><img class="shot" src="'+c+`" alt="Mod V pastes cells copied from a spreadsheet as a table; with the cursor in the table, Mod V pastes two more rows, and the table grows to take them"><ul><li><strong>Paste cells</strong> you copied in LibreOffice Calc, Excel, Google Sheets or Numbers, or a table from a web page or Word, and you get a table. Its first row becomes the header. A column keeps its alignment when all its cells agree, like numbers aligned right.</li><li><strong>Paste into a table</strong>, and the cells fill from the cursor, or fill the cells you selected. The table grows when they need more room. The pasted cells fit in where they land: header cells in the header row, plain cells below it.</li><li><strong>Copy cells</strong>, selected with <code>Shift</code> + arrows or <code>Mod</code> <code>A</code>, and paste them into a spreadsheet: every cell lands in its own cell there.</li><li><strong>Paste as plain text</strong> in the right-click menu keeps copied cells as text.</li></ul><p>Tables pasted from elsewhere get their widths from their content, like any other table.</p><h2 id="saving" tabindex="-1">How tables are saved <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;How tables are saved {#saving}&quot;">​</a></h2><p>A table is saved as a markdown table, with the columns lined up so the file reads well in any text editor:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Name   | Qty | Price |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| ------ | --: | ----: |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Apples |   3 |  1.20 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Pears  |  12 |  0.80 |</span></span></code></pre></div><p>Line breaks in a cell are saved as <code>&lt;br&gt;</code>, and the colons in the second line keep the alignment of each column.</p><p>A markdown table holds one line of text per cell. When a table needs more, like a list or several paragraphs in a cell, merged cells, a header column, a caption or column widths you set, Blank saves that one table as an HTML table in the same markdown file, and tells you the first time. GitHub, Obsidian, Typora and pandoc show it as a table as well. Once the table fits a markdown table again, Blank saves it as one.</p><p>Blank opens both kinds, so you can also open markdown files with tables written in other editors.</p><h2 id="export" tabindex="-1">PDF and Word <a class="header-anchor" href="#export" aria-label="Permalink to &quot;PDF and Word {#export}&quot;">​</a></h2><p>Tables go into your <a href="./files">PDF and Word documents</a> the way you see them in Blank: the tinted header, the lines between the rows and columns, the alignment of each column, merged cells and the caption above the table. Everything a cell holds comes along too: several paragraphs, lists, quotes, code and images. Columns get the widths you set, or else their width from their content, like in the editor.</p><ul><li>A table longer than a page repeats its header row at the top of every page.</li><li>Rows stay whole instead of breaking across two pages, unless a row is too tall for one.</li><li>A caption never ends a page on its own: it moves to the next page with its table.</li></ul><p>In Word, tables are real Word tables and the caption uses Word&#39;s caption style, so the document stays easy to edit. When you <a href="./files#open-word-documents">open a Word document</a>, its tables come along with their merged cells, header rows and captions.</p>`,48)])])}const f=t(h,[["render",p]]);export{k as __pageData,f as default};
